import logo from './logo.svg';
import './App.css';
import axios from "axios";

import { useEffect } from 'react';

function App() {
  useEffect(() => {
    axios.get("localhost:5104/")
      .then((res) => console.log(res.data))
      .catch((err) => console.error(err));
    }, []
  );

  return (
    <div className="App">
      Backend request sent — check console!
    </div>
  );
}

export default App;
